 public static void main(String[]args)throws Exception {Looper.getMainLooper();try{if(args.length>0){if(args[0].equals("review-stage"))reviewStage();else if(args[0].equals("review-supplier"))reviewSupplier();else if(args[0].equals("review-phase"))reviewPhase();else if(args[0].equals("review-stage-close"))reviewStageClose();else if(args[0].equals("review-cancel"))reviewCancellation();else isolated(args[0]);}else{stageChecks();closeWitnessChecks();partialStageChecks();adapterChecks();errorClosureChecks();coordinatorChecks();}System.out.println("PASS DOCX publication "+checks+" checks "+Arrays.toString(args));}finally{pool().shutdownNow();check(pool().awaitTermination(5,TimeUnit.SECONDS),"worker terminates");}}
